app_css:
.tool-app-certwatch { color: #0f3f3a; max-width: 940px; margin-inline:auto; }
.tool-app-certwatch .cw-h { margin: 18px 0 8px; font-size: 15px; }
.tool-app-certwatch .cw-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 10px; }
.tool-app-certwatch .cw-stat { background: #f0fdfa; border: 1px solid #99f6e4; border-radius: 10px; padding: 10px 14px; display: flex; flex-direction: column; gap: 2px; }
.tool-app-certwatch .cw-stat span { font-size: 12px; font-weight: 600; color: #115e59; }
.tool-app-certwatch .cw-stat strong { font-size: 24px; }
.tool-app-certwatch .cw-stat.cw-warn { background: #fffbeb; border-color: #fde68a; }
.tool-app-certwatch .cw-stat.cw-warn strong { color: #b45309; }
.tool-app-certwatch .cw-stat.cw-bad { background: #fef2f2; border-color: #fecaca; }
.tool-app-certwatch .cw-stat.cw-bad strong { color: #b91c1c; }
.tool-app-certwatch .cw-alerts { list-style: none; padding: 0; margin: 8px 0; }
.tool-app-certwatch .cw-alerts li { padding: 8px 12px; border-radius: 8px; margin-bottom: 6px; font-size: 14px; }
.tool-app-certwatch .cw-alerts li.cw-exp { background: #fef2f2; color: #991b1b; border: 1px solid #fecaca; }
.tool-app-certwatch .cw-alerts li.cw-soon { background: #fffbeb; color: #92400e; border: 1px solid #fde68a; }
.tool-app-certwatch .cw-alerts li.cw-none { background: #f0fdfa; color: #115e59; border: 1px solid #99f6e4; }
.tool-app-certwatch .cw-cols { display: grid; grid-template-columns: 320px 1fr; gap: 18px; }
@media (max-width: 760px) { .tool-app-certwatch .cw-cols { grid-template-columns: 1fr; } }
.tool-app-certwatch .cw-form { display: flex; flex-direction: column; gap: 10px; background: #f8fafc; border-radius: 10px; padding: 12px; margin-bottom: 6px; }
.tool-app-certwatch label { display: flex; flex-direction: column; font-size: 12px; font-weight: 600; gap: 4px; }
.tool-app-certwatch input[type="text"], .tool-app-certwatch input[type="email"], .tool-app-certwatch input[type="date"], .tool-app-certwatch textarea, .tool-app-certwatch select { border: 1px solid #99f6e4; border-radius: 8px; padding: 8px 10px; font-size: 14px; width: 100%; box-sizing: border-box; background: #fff; }
.tool-app-certwatch .cw-btn { background: #0D9488; color: #fff; border: none; border-radius: 10px; padding: 10px 18px; font-size: 14px; font-weight: 700; cursor: pointer; }
.tool-app-certwatch .cw-btn:hover { background: #0f766e; }
.tool-app-certwatch .cw-btn-ghost { background: #ccfbf1; color: #0f766e; }
.tool-app-certwatch .cw-btn-ghost:hover { background: #99f6e4; }
.tool-app-certwatch .cw-formbtns { display: flex; gap: 8px; }
.tool-app-certwatch .cw-vendor { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 10px; padding: 12px; margin-bottom: 12px; }
.tool-app-certwatch .cw-vendor-head { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.tool-app-certwatch .cw-vendor-head strong { font-size: 15px; }
.tool-app-certwatch .cw-vendor-head .cw-contact { font-size: 12px; color: #475569; }
.tool-app-certwatch .cw-coi { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; background: #fff; border: 1px solid #e2e8f0; border-radius: 8px; padding: 8px 10px; margin-top: 8px; font-size: 13px; }
.tool-app-certwatch .cw-badge { font-size: 11px; font-weight: 700; border-radius: 20px; padding: 3px 10px; white-space: nowrap; }
.tool-app-certwatch .cw-badge.cw-b-ok { background: #d1fae5; color: #065f46; }
.tool-app-certwatch .cw-badge.cw-b-warn { background: #fef3c7; color: #92400e; }
.tool-app-certwatch .cw-badge.cw-b-exp { background: #fee2e2; color: #991b1b; }
.tool-app-certwatch .cw-coi .cw-meta { color: #475569; font-size: 12px; }
.tool-app-certwatch .cw-link { background: none; border: none; cursor: pointer; font-size: 13px; font-weight: 700; }
.tool-app-certwatch .cw-edit { color: #0D9488; }
.tool-app-certwatch .cw-del { color: #b91c1c; }
.tool-app-certwatch .cw-actions { display: flex; gap: 10px; margin: 18px 0; flex-wrap: wrap; }
.tool-app-certwatch .tool-print-doc { display: none; }
@media print {
  .tool-app-certwatch .cw-screen { display: none !important; }
  .tool-app-certwatch .tool-print-doc { display: block !important; color: #000; }
  .tool-app-certwatch .tool-print-doc table { width: 100%; border-collapse: collapse; margin: 12px 0; }
  .tool-app-certwatch .tool-print-doc th, .tool-app-certwatch .tool-print-doc td { border: 1px solid #999; padding: 6px; text-align: left; font-size: 13px; }
}

app_js:
(function () {
  'use strict';
  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  var LS_KEY = 'toolapp-certwatch-data';
  var editingCoiId = null;
  function uid() { return 'id' + Date.now().toString(36) + Math.floor(Math.random() * 1e6).toString(36); }
  function load() {
    try {
      var d = JSON.parse(localStorage.getItem(LS_KEY));
      if (d && d.vendors && d.cois) return d;
    } catch (e) {}
    return { vendors: [], cois: [] };
  }
  function save(d) {
    try { localStorage.setItem(LS_KEY, JSON.stringify(d)); } catch (e) {}
  }
  function parseDate(str) {
    if (!str) return null;
    var p = str.split('-');
    if (p.length !== 3) return null;
    return new Date(parseInt(p[0], 10), parseInt(p[1], 10) - 1, parseInt(p[2], 10));
  }
  function todayMid() {
    var t = new Date();
    return new Date(t.getFullYear(), t.getMonth(), t.getDate());
  }
  function daysLeft(expiryStr) {
    var d = parseDate(expiryStr);
    if (!d) return null;
    return Math.round((d.getTime() - todayMid().getTime()) / 864e5);
  }
  function fmtDate(str) {
    var d = parseDate(str);
    if (!d) return '—';
    var m = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    return m[d.getMonth()] + ' ' + d.getDate() + ', ' + d.getFullYear();
  }
  function statusOf(coi) {
    var dl = daysLeft(coi.expiry);
    if (dl == null) return { key: 'warn', label: 'No date', dl: null };
    if (dl < 0) return { key: 'exp', label: 'Expired ' + Math.abs(dl) + 'd ago', dl: dl };
    if (dl === 0) return { key: 'exp', label: 'Expires today', dl: dl };
    if (dl <= 30) return { key: 'warn', label: 'Expires in ' + dl + 'd', dl: dl };
    return { key: 'ok', label: 'OK · ' + dl + 'd left', dl: dl };
  }
  function vendorName(d, id) {
    for (var i = 0; i < d.vendors.length; i++) {
      if (d.vendors[i].id === id) return d.vendors[i].name;
    }
    return 'Unknown vendor';
  }
  function render() {
    var d = load();
    var i, st;
    var expired = 0, warn = 0, active = 0;
    var alerts = [];
    for (i = 0; i < d.cois.length; i++) {
      st = statusOf(d.cois[i]);
      if (st.key === 'exp') { expired++; alerts.push({ coi: d.cois[i], st: st }); }
      else if (st.key === 'warn') { warn++; if (st.dl != null && st.dl <= 30) alerts.push({ coi: d.cois[i], st: st }); }
      else { active++; }
    }
    $('cw-stat-vendors').textContent = d.vendors.length;
    $('cw-stat-active').textContent = active;
    $('cw-stat-warn').textContent = warn;
    $('cw-stat-expired').textContent = expired;
    alerts.sort(function (a, b) { return a.st.dl - b.st.dl; });
    var al = $('cw-alerts');
    al.innerHTML = '';
    if (!alerts.length) {
      var li0 = document.createElement('li');
      li0.className = 'cw-none';
      li0.textContent = d.cois.length ? 'Nothing expiring in the next 30 days. You are covered.' : 'No COIs tracked yet — add a vendor and its first certificate above.';
      al.appendChild(li0);
    } else {
      for (i = 0; i < alerts.length; i++) {
        var li = document.createElement('li');
        li.className = alerts[i].st.key === 'exp' ? 'cw-exp' : 'cw-soon';
        li.textContent = alerts[i].coi.type + ' — ' + vendorName(d, alerts[i].coi.vendorId) + ': ' + alerts[i].st.label;
        al.appendChild(li);
      }
    }
    var sel = $('cw-coi-vendor');
    sel.innerHTML = '';
    for (i = 0; i < d.vendors.length; i++) {
      var opt = document.createElement('option');
      opt.value = d.vendors[i].id;
      opt.textContent = d.vendors[i].name;
      sel.appendChild(opt);
    }
    var box = $('cw-vendors');
    box.innerHTML = '';
    if (!d.vendors.length) {
      var p = document.createElement('p');
      p.style.color = '#64748b';
      p.textContent = 'No vendors yet.';
      box.appendChild(p);
      return;
    }
    for (i = 0; i < d.vendors.length; i++) {
      (function (v) {
        var wrap = document.createElement('div');
        wrap.className = 'cw-vendor';
        var head = document.createElement('div');
        head.className = 'cw-vendor-head';
        var t = document.createElement('div');
        t.innerHTML = '<strong>' + esc(v.name) + '</strong>' + (v.email ? '<div class="cw-contact">' + esc(v.email) + '</div>' : '');
        var delV = document.createElement('button');
        delV.type = 'button';
        delV.className = 'cw-link cw-del';
        delV.textContent = 'Remove';
        delV.onclick = function () {
          if (!confirm('Remove ' + v.name + ' and all its COIs?')) return;
          var dd = load();
          dd.vendors = dd.vendors.filter(function (x) { return x.id !== v.id; });
          dd.cois = dd.cois.filter(function (x) { return x.vendorId !== v.id; });
          save(dd); render();
        };
        head.appendChild(t);
        head.appendChild(delV);
        wrap.appendChild(head);
        var vcois = d.cois.filter(function (c) { return c.vendorId === v.id; });
        vcois.sort(function (a, b) {
          var da = daysLeft(a.expiry), db = daysLeft(b.expiry);
          return (da == null ? 1e9 : da) - (db == null ? 1e9 : db);
        });
        if (!vcois.length) {
          var none = document.createElement('div');
          none.className = 'cw-meta';
          none.style.marginTop = '8px';
          none.textContent = 'No COIs logged yet.';
          wrap.appendChild(none);
        }
        vcois.forEach(function (c) {
          var s = statusOf(c);
          var row = document.createElement('div');
          row.className = 'cw-coi';
          var badge = document.createElement('span');
          badge.className = 'cw-badge cw-b-' + s.key;
          badge.textContent = s.label;
          var info = document.createElement('div');
          n          info.innerHTML = '<strong>' + esc(c.type) + '</strong><div class="cw-meta">' +
            (c.insurer ? esc(c.insurer) : 'No insurer') +
            (c.policy ? ' · ' + esc(c.policy) : '') +
            ' · Expires ' + esc(fmtDate(c.expiry)) + '</div>';
          var edit = document.createElement('button');
          edit.type = 'button';
          edit.className = 'cw-link cw-edit';
          edit.textContent = 'Edit';
          edit.onclick = function () { startEdit(c); };
          var del = document.createElement('button');
          del.type = 'button';
          del.className = 'cw-link cw-del';
          del.textContent = 'Delete';
          del.onclick = function () {
            if (!confirm('Delete this COI record?')) return;
            var dd = load();
            dd.cois = dd.cois.filter(function (x) { return x.id !== c.id; });
            save(dd); render();
          };
          row.appendChild(badge);
          row.appendChild(info);
          row.appendChild(edit);
          row.appendChild(del);
          wrap.appendChild(row);
        });
        box.appendChild(wrap);
      })(d.vendors[i]);
    }
  }
  function startEdit(c) {
    editingCoiId = c.id;
    $('cw-coi-vendor').value = c.vendorId;
    $('cw-coi-type').value = c.type;
    $('cw-coi-insurer').value = c.insurer || '';
    $('cw-coi-policy').value = c.policy || '';
    $('cw-coi-effective').value = c.effective || '';
    $('cw-coi-expiry').value = c.expiry || '';
    $('cw-coi-submit').textContent = 'Save changes';
    $('cw-coi-cancel').hidden = false;
    $('cw-coi-expiry').focus();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }
  function cancelEdit() {
    editingCoiId = null;
    $('cw-coi-form').reset();
    $('cw-coi-submit').textContent = 'Add COI';
    $('cw-coi-cancel').hidden = true;
  }
  function exportCSV() {
    var d = load();
    var rows = [['Vendor', 'Contact', 'Coverage', 'Insurer', 'Policy #', 'Effective', 'Expiry', 'Status']];
    d.cois.forEach(function (c) {
      var v = null;
      for (var i = 0; i < d.vendors.length; i++) if (d.vendors[i].id === c.vendorId) v = d.vendors[i];
      rows.push([
        v ? v.name : '', v && v.email ? v.email : '', c.type, c.insurer || '',
        c.policy || '', c.effective || '', c.expiry || '', statusOf(c).label
      ]);
    });
    var csv = rows.map(function (r) {
      return r.map(function (cell) { return '"' + String(cell).replace(/"/g, '""') + '"'; }).join(',');
    }).join('\n');
    var blob = new Blob([csv], { type: 'text/csv' });
    var a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'certwatch-export.csv';
    document.body.appendChild(a);
    a.click();
    setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 500);
  }
  function printReport() {
    var d = load();
    var rowsHtml = '';
    var sorted = d.cois.slice().sort(function (a, b) {
      var da = daysLeft(a.expiry), db = daysLeft(b.expiry);
      return (da == null ? 1e9 : da) - (db == null ? 1e9 : db);
    });
    for (var i = 0; i < sorted.length; i++) {
      var c = sorted[i];
      rowsHtml += '<tr><td>' + esc(vendorName(d, c.vendorId)) + '</td><td>' + esc(c.type) + '</td><td>' +
        esc(c.insurer || '—') + '</td><td>' + esc(c.policy || '—') + '</td><td>' + esc(fmtDate(c.expiry)) +
        '</td><td>' + esc(statusOf(c).label) + '</td></tr>';
    }
    $('cw-printdoc').innerHTML =
      '<h1>Certificate of Insurance — Compliance Report</h1>' +
      '<p>Generated ' + esc(new Date().toLocaleDateString()) + ' · ' + d.vendors.length + ' vendors, ' +
      d.cois.length + ' COIs on file.</p>' +
      '<table><thead><tr><th>Vendor</th><th>Coverage</th><th>Insurer</th><th>Policy #</th>' +
      '<th>Expiry</th><th>Status</th></tr></thead><tbody>' + rowsHtml + '</tbody></table>';
    window.print();
  }
  $('cw-vendor-form').addEventListener('submit', function (e) {
    e.preventDefault();
    var name = $('cw-vendor-name').value.trim();
    if (!name) return;
    var d = load();
    d.vendors.push({ id: uid(), name: name, email: $('cw-vendor-email').value.trim(), notes: $('cw-vendor-notes').value.trim() });
    save(d);
    this.reset();
    render();
  });
  $('cw-coi-form').addEventListener('submit', function (e) {
    e.preventDefault();
    var vendorId = $('cw-coi-vendor').value;
    var expiry = $('cw-coi-expiry').value;
    if (!vendorId || !expiry) return;
    var d = load();
    var rec = {
      vendorId: vendorId,
      type: $('cw-coi-type').value,
      insurer: $('cw-coi-insurer').value.trim(),
      policy: $('cw-coi-policy').value.trim(),
      effective: $('cw-coi-effective').value,
      expiry: expiry
    };
    if (editingCoiId) {
      rec.id = editingCoiId;
      for (var i = 0; i < d.cois.length; i++) {
        if (d.cois[i].id === editingCoiId) { d.cois[i] = rec; break; }
      }
      cancelEdit();
    } else {
      rec.id = uid();
      d.cois.push(rec);
      this.reset();
    }
    save(d);
    render();
  });
  $('cw-coi-cancel').addEventListener('click', cancelEdit);
  $('cw-csv').addEventListener('click', exportCSV);
  $('cw-print').addEventListener('click', printReport);
  render();
})();
